 private Outcome run(Path classes,Path official,Path workspace)throws Exception{Exception last=null;for(int attempt=0;attempt<2;attempt++){try{if(attempt>0){Thread.sleep(5000L);recreate(workspace);}String output=capture(root,Arrays.asList("java","-classpath",classes+separator()+product("api"),"worldline.smoke.slimesplitsetb173.SlimeSplitSetSmoke",official.toString(),workspace.toString(),Integer.toString(freePort()),value(config,"seed"),value(config,"username"),value(config,"chunk.x"),value(config,"chunk.z")));return new Outcome(line(output,"WORLDLINE_M412_TRACE="),line(output,"WORLDLINE_M412_SIGNATURE="),line(output,"WORLDLINE_M412_SPLIT="));}catch(Exception e){last=e;if(attempt==0&&eof(e))continue;throw e;}}throw last;}
